import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.BFzNpupd.js";const h=JSON.parse('{"title":"Non-Functional Requirements (NFRs)","description":"","frontmatter":{},"headers":[],"relativePath":"standards/04_NON_FUNCTIONAL_REQUIREMENTS.md","filePath":"standards/04_NON_FUNCTIONAL_REQUIREMENTS.md"}'),n={name:"standards/04_NON_FUNCTIONAL_REQUIREMENTS.md"};function r(s,e,l,c,d,u){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="non-functional-requirements-nfrs" tabindex="-1">Non-Functional Requirements (NFRs) <a class="header-anchor" href="#non-functional-requirements-nfrs" aria-label="Permalink to &quot;Non-Functional Requirements (NFRs)&quot;">​</a></h1><p>Because Speed Assist is a continuous-tracking app targeting safety and potentially fleets, Non-Functional Requirements are just as critical as the features themselves.</p><h2 id="_1-battery-resource-optimization" tabindex="-1">1. Battery &amp; Resource Optimization <a class="header-anchor" href="#_1-battery-resource-optimization" aria-label="Permalink to &quot;1. Battery &amp; Resource Optimization&quot;">​</a></h2><p>Continuous GPS polling is the #1 reason users uninstall driving apps.</p><ul><li><strong>Adaptive Polling:</strong> Do not request high-accuracy 1-second GPS updates if the user is stationary for &gt; 5 minutes. Downscale the request interval dynamically.</li><li><strong>Wakelocks:</strong> Use <code>ForegroundService</code> properly with clear notifications rather than raw CPU Wakelocks whenever possible. Release resources in <code>onDestroy()</code> or <code>onStop()</code>.</li><li><strong>Auto-Start Efficiency:</strong> Leverage <code>:speed-autostart</code> (Google Play Services <code>IN_VEHICLE</code> transition) for zero-friction background trip detection instead of continuous CPU wakelocks, saving massive battery power while waiting for trips to start.</li></ul><h2 id="_2-location-privacy-compliance-crucial" tabindex="-1">2. Location &amp; Privacy Compliance (Crucial) <a class="header-anchor" href="#_2-location-privacy-compliance-crucial" aria-label="Permalink to &quot;2. Location &amp; Privacy Compliance (Crucial)&quot;">​</a></h2><ul><li><strong>Permissions:</strong> Always handle permission degradation gracefully. If <code>ACCESS_BACKGROUND_LOCATION</code> is denied but foreground is granted, the app should still function while open.</li><li><strong>Dialogs:</strong> Adhere strictly to Google Play policies by showing explicit &quot;Prominent Disclosure&quot; rationale dialogs <em>before</em> requesting background location. (See <code>dialogs.showLocationPermissionRationale</code>).</li></ul><h2 id="_3-performance-stability" tabindex="-1">3. Performance &amp; Stability <a class="header-anchor" href="#_3-performance-stability" aria-label="Permalink to &quot;3. Performance &amp; Stability&quot;">​</a></h2><ul><li><strong>Compose Recomposition:</strong> Avoid passing unstable data classes or heavily mutating lists directly to Compose functions. Use <code>remember</code> and <code>key</code> blocks. Monitor for &quot;jank&quot; caused by excessive recomposition in HUD modes.</li><li><strong>GPS Jitter (EMA &amp; Schmitt Trigger):</strong> Raw GPS data is noisy at low speeds. The app implements Exponential Moving Average (EMA $\\alpha = 0.3$) smoothing and Dual Schmitt Trigger Hysteresis ($+1.0\\text{ km/h} / -3.0\\text{ km/h}$) to eliminate velocity jitter and prevent alarm fluttering at boundary limits.</li></ul><h2 id="_4-background-resiliency" tabindex="-1">4. Background Resiliency <a class="header-anchor" href="#_4-background-resiliency" aria-label="Permalink to &quot;4. Background Resiliency&quot;">​</a></h2><ul><li><strong>OS Kill Prevention:</strong> Android (Doze mode) aggressively kills background apps. Always utilize a highly optimized <code>ForegroundService</code> with a persistent, non-dismissible notification to prevent the OS from silently killing the app during a drive.</li></ul><h2 id="_5-safety-distraction-optimization-legal-nfr" tabindex="-1">5. Safety &amp; Distraction Optimization (Legal NFR) <a class="header-anchor" href="#_5-safety-distraction-optimization-legal-nfr" aria-label="Permalink to &quot;5. Safety &amp; Distraction Optimization (Legal NFR)&quot;">​</a></h2><ul><li><strong>Voice &amp; Audio First:</strong> The UI must not distract the driver. Once driving begins, the screen should require zero interaction. Rely on audio escalation and high-contrast, glanceable UIs (HUD mode).</li><li><strong>Drive Mode Lockout:</strong> Consider disabling complex UI interactions or typing while the vehicle is in motion to comply with hands-free and distraction laws.</li><li><strong>HUD Mode:</strong> The <code>HudDisplay</code> component enforces distraction safety by utilizing a high-contrast, pure OLED black (<code>#000000</code>) background intended strictly for windshield reflection during night driving, eliminating peripheral glare.</li></ul><h2 id="_6-hardware-heterogeneity-handling" tabindex="-1">6. Hardware Heterogeneity Handling <a class="header-anchor" href="#_6-hardware-heterogeneity-handling" aria-label="Permalink to &quot;6. Hardware Heterogeneity Handling&quot;">​</a></h2><ul><li><strong>Calibration Offset:</strong> Different phones have varying GPS chip qualities, and car speedometers are intentionally calibrated to show faster speeds than reality. Allow users to manually adjust the app&#39;s speed calculation by a percentage offset to match their dashboard perfectly.</li></ul><h2 id="_7-app-size-offline-capability" tabindex="-1">7. App Size &amp; Offline Capability <a class="header-anchor" href="#_7-app-size-offline-capability" aria-label="Permalink to &quot;7. App Size &amp; Offline Capability&quot;">​</a></h2><ul><li><strong>Zero Cloud Reliance:</strong> The core speed tracking and alerting must function 100% offline without an internet connection. Do not rely on cloud processing for real-time safety critical alerts.</li><li><strong>Lightweight Footprint:</strong> Total download size and runtime memory footprint must both remain $&lt; 5\\text{ MB}$.</li></ul><h2 id="_8-sdk-modular-architecture-b2b-ecosystem" tabindex="-1">8. SDK Modular Architecture (B2B Ecosystem) <a class="header-anchor" href="#_8-sdk-modular-architecture-b2b-ecosystem" aria-label="Permalink to &quot;8. SDK Modular Architecture (B2B Ecosystem)&quot;">​</a></h2><p>Per the research failure analysis, the consumer app market is tough, and B2B SDK licensing is the future.</p><ul><li><strong>Core Independence:</strong> The location tracking and speed calculation logic (<code>TelematicsEngine</code>, <code>SpeedWatcher</code>, <code>ISpeedRepository</code>) in <code>:speed-core</code> is completely decoupled with zero UI or ad dependencies.</li><li><strong>Modular Mindset:</strong> Features are isolated across <code>:speed-core</code>, <code>:speed-ui</code>, <code>:speed-overlay</code>, <code>:speed-autostart</code>, and <code>:speed-bom</code> with minimal public API surface.</li></ul><h2 id="_9-app-startup-launch-weight" tabindex="-1">9. App Startup &amp; Launch Weight <a class="header-anchor" href="#_9-app-startup-launch-weight" aria-label="Permalink to &quot;9. App Startup &amp; Launch Weight&quot;">​</a></h2><ul><li><strong>Lightweight Initialization:</strong> The app must open instantly. Do not initialize heavy SDKs, database migrations, or complex location requests synchronously on the main thread during <code>Application.onCreate()</code> or <code>Activity.onCreate()</code>. Defer non-essential initializations until after the first frame has rendered.</li></ul>',22)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
